<?php
$csrf=login('qa5');$designations=http('page=designations');
ok(str_contains($designations['body'],'Jefe inmediato por dependencias') && str_contains($designations['body'],'Historial de designaciones'),'Talento Humano accede a designaciones por dependencia y sus vigencias');
$newAssignment=http('page=designations',['action'=>'designation','csrf'=>$csrf,'role'=>'manager','user_id'=>'10','alternate_id'=>'7','start_date'=>date('Y-m-d',strtotime('+2 days')),'department_ids[0]'=>'2','department_ids[1]'=>'3'],true);
ok($newAssignment['code']===302,'Registro por HTTP de un jefe para varias dependencias con fecha futura');
ok(str_contains(http('page=designations')['body'],'Programada'),'La designación futura permanece identificada en el historial');
$userForm=http('page=users&id=9');ok(str_contains($userForm['body'],'name="birth_date"') && str_contains($userForm['body'],'value="payroll"') && !str_contains($userForm['body'],'name="manager_id"'),'Directorio contiene fecha de nacimiento y Nómina, sin jefe individual editable');
$csrf=login('qa14');
ok(str_contains(http('page=designations')['body'],'requiere un administrador'),'Un solicitante no puede consultar ni administrar designaciones');
$newForm=http('page=new')['body'];
ok(str_contains($newForm,'Vigencia del beneficio de Cumpleaños') && !str_contains($newForm,'data-special') && !str_contains($newForm,'special_note') && !str_contains($newForm,'Día +1'),'El formulario conserva Cumpleaños y ya no muestra horarios especiales');
$actPost=['action'=>'act','csrf'=>$csrf,'number'=>'ACTO-HTTP-NOMINA','issued_on'=>date('Y-m-d'),'expires_on'=>'2027-12-31','hours'=>'8.5','supports[0]'=>new CURLFile($root.'/.work/soporte.pdf','application/pdf','acto-nomina.pdf')];
ok(http('page=acts',$actPost,true)['code']===302,'El funcionario registra un acto para validación exclusiva de Nómina');
$csrf=login('qa12');$payrollActs=http('page=acts')['body'];
$dom=new DOMDocument();$dom->loadHTML($payrollActs);$xp=new DOMXPath($dom);
$actNodes=$xp->query("//article[.//h3[text()='Resolución No. ACTO-HTTP-NOMINA']]//input[@name='id']/@value");
ok($actNodes->length===1,'Nómina recibe el acto pendiente con acciones de revisión');$payrollActId=$actNodes->item(0)->nodeValue;
$fileNodes=$xp->query("//article[.//h3[text()='Resolución No. ACTO-HTTP-NOMINA']]//a[contains(@href,'page=download')]/@href");
ok($fileNodes->length===1 && str_starts_with(http(ltrim($fileNodes->item(0)->nodeValue,'/?'))['body'],'%PDF-'),'Nómina puede descargar el soporte antes de decidir');
$csrf=login('qa7');$noPayroll=http('page=acts',['action'=>'review_act','csrf'=>$csrf,'id'=>$payrollActId,'decision'=>'approved','comment'=>'Intento solo Talento Humano'],true);
ok(str_contains($noPayroll['body'],'requiere el rol de Nómina'),'Talento Humano sin rol de Nómina no puede validar actos por HTTP');
$csrf=login('qa12');$approvedAct=http('page=acts',['action'=>'review_act','csrf'=>$csrf,'id'=>$payrollActId,'decision'=>'approved','comment'=>'Nómina verifica el documento y las horas'],true);
ok($approvedAct['code']===302 && str_contains(http('page=acts')['body'],'Revisado por Nómina QA'),'Aprobación de acto por HTTP conserva y muestra responsable y fecha');
$csrf=login('qa14');
$normalPost=['action'=>'submit','csrf'=>$csrf,'category_id'=>'2','justification'=>'Solicitud por horario laboral oficial configurado','slots[0][date]'=>'2026-12-14','slots[0][mode]'=>'full','supports[0]'=>new CURLFile($root.'/.work/soporte.pdf','application/pdf','soporte-jornada.pdf')];
$normalResponse=http('page=new',$normalPost,true);
ok($normalResponse['code']===302 && preg_match('/Location: \/\?page=request&id=(\d+)/i',$normalResponse['headers'],$normalMatch)===1,'Se registra una jornada oficial completa después del retiro');
$normalId=$normalMatch[1];$normalDetail=http('page=request&id='.$normalId)['body'];
ok(str_contains($normalDetail,'8 h 30 min') && !str_contains($normalDetail,'Jornada especial'),'El detalle usa la duración de la jornada configurada');
ok(str_starts_with(http('page=pdf&id='.$normalId)['body'],'%PDF-'),'Se genera el PDF después de retirar los campos de horario especial');
$normalPost['slots[0][date]']='2026-12-13';
ok(str_contains(http('page=new',$normalPost,true)['body'],'no es un día laborable'),'El formulario no admite solicitudes en domingo');
$normalPost['slots[0][date]']='2026-12-15';$normalPost['slots[0][special]']='1';
ok(str_contains(http('page=new',$normalPost,true)['body'],'solo se admite la jornada laboral configurada'),'El servidor rechaza los campos enviados por un formulario anterior');
$estimate=http('page=estimate&date=2026-12-14');$estimateData=json_decode($estimate['body'],true);
ok($estimateData!==null && $estimateData['minutes']===510,'El cálculo interactivo conserva la jornada oficial');
$obsoleteEstimate=http('page=estimate&'.http_build_query(['slot'=>['special'=>1,'date'=>'2026-12-13']]));
ok($obsoleteEstimate['code']===403,'La estimación ya no procesa horarios enviados por el cliente');
