ok(!str_contains(http('page=balances&cutoff='.date('Y-m-d'))['body'],'Funcionario diciembre'),'El jefe saliente no ve saldos posteriores al fin de su designación');
$csrf=login('qa11');
ok(str_contains(http('page=balances&cutoff='.date('Y-m-d'))['body'],'Funcionario diciembre'),'El jefe vigente consulta los saldos de su dependencia');
$csrf=login('qa8');
ok(!str_contains(http('page=balances&cutoff='.date('Y-m-d'))['body'],'Funcionario diciembre'),'La consulta de saldos impide acceder a dependencias ajenas');
